(()=>{'use strict';const cfg=window.PATIYIZ_CONFIG;let client=null;const get=()=>client||(client=window.supabase.createClient(cfg.supabaseUrl,cfg.supabasePublishableKey));const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));async function draw(){const dashboard=document.getElementById('dashboard');if(!dashboard||dashboard.classList.contains('hidden'))return;let box=document.getElementById('pati-admin-cashout');if(!box){box=document.createElement('section');box.id='pati-admin-cashout';box.style.cssText='margin:22px 0;padding:18px;background:#fff;border:1px solid #ddd;border-radius:15px';box.innerHTML='<h2>Nakit Talep Başvuruları</h2><p>IBAN yalnızca yetkili yönetici incelemesi içindir. Bu panel ödeme yapmaz.</p><button type="button" id="cashout-admin-refresh">Başvuruları yenile</button><div id="cashout-admin-list">Yükleniyor…</div>';dashboard.appendChild(box)}try{const c=get();const permission=await c.rpc('patiyiz_admin_dashboard');if(permission.error)throw permission.error;const result=await c.from('patiyiz_cashout_requests').select('id,user_id,full_name,iban,amount_try,points_requested,status,created_at').order('created_at',{ascending:false}).limit(100);if(result.error)throw result.error;document.getElementById('cashout-admin-list').innerHTML=(result.data||[]).map(x=>'<article style="padding:12px 0;border-bottom:1px solid #eee"><strong>'+esc(x.full_name)+'</strong> · '+Number(x.amount_try)+' TL · '+esc(x.status)+'<p>'+esc(x.iban)+'</p><small>Talep edilen: '+Number(x.points_requested)+' puan · '+new Date(x.created_at).toLocaleString('tr-TR')+' · Üye: '+esc(x.user_id)+'</small></article>').join('')||'<p>Henüz nakit talebi yok.</p>'}catch(e){document.getElementById('cashout-admin-list').textContent='Talepler yüklenemedi veya yönetici yetkisi yok.'}}document.addEventListener('click',e=>{if(e.target.id==='cashout-admin-refresh')void draw()});new MutationObserver(()=>{if(document.getElementById('dashboard')&&!document.getElementById('dashboard').classList.contains('hidden')&&!document.getElementById('pati-admin-cashout'))void draw()}).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});})();